public int getBuildNumber()
{
  int buildNumber = -1;
  try
  {
    final PackageInfo pi = getPackageManager().getPackageInfo(getPackageName(), 0);
    buildNumber = pi.versionCode;
  }
  catch (final NameNotFoundException e)
  {
